def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    dist = distance_to(enemy.x, enemy.y)
    brg = bearing_to(enemy.x, enemy.y)
    # Stay away from the enemy's spinner side; their disc is on the right.
    spin_side = None
    for s in ("left", "right", "front", "back", "top"):
        w = enemy.weapons.get(s)
        if w is not None and w.get("type") == "spinner":
            spin_side = s
            break
    if dist > 1.5 and spin_side in ("left", "right"):
        eh = enemy.heading
        off = eh + 90.0 if spin_side == "right" else eh - 90.0
        tx = enemy.x + cos(radians(off)) * 1.3
        ty = enemy.y + sin(radians(off)) * 1.3
        if hypot(tx, ty) < 6.3:
            brg = bearing_to(tx, ty)
    turn = brg / 90.0
    if turn > 1.0:
        turn = 1.0
    elif turn < -1.0:
        turn = -1.0
    fwd = 1.0
    left = fwd + turn
    right = fwd - turn
    if left > 1.0:
        left = 1.0
    elif left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    elif right < -1.0:
        right = -1.0
    return (left, right)

